import heapq


def _dependency_solver(data, prefer_max, descending):
    packages = data["packages"]
    names = sorted(packages, reverse=descending)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        choices.append([-1] + versions)

    best_vector = None
    best_versions = None
    rows_by_version = {
        name: {row["version"]: row for row in packages[name]}
        for name in names
    }
    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0]
               or selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in roots and selected[name] == -1 for name in roots):
            continue
        edges = {name: [] for name, version in selected.items() if version != -1}
        valid = True
        for name, version in selected.items():
            if version == -1:
                continue
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = selected[other]
                if other_version == -1 or not dep["min"] <= other_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # All selected packages must be reachable from roots: pins and other
        # unconstrained packages never install packages on their own.
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(edges.get(name, []))
        if reached != {name for name, version in selected.items() if version != -1}:
            continue

        state, cyclic = {}, False
        def visit(name):
            nonlocal cyclic
            if state.get(name) == 1:
                cyclic = True
                return
            if state.get(name) == 2:
                return
            state[name] = 1
            for other in edges[name]:
                visit(other)
                if cyclic:
                    return
            state[name] = 2
        for name in edges:
            visit(name)
            if cyclic:
                break
        if cyclic:
            continue

        vector = tuple(values)
        if best_vector is None or (vector > best_vector if prefer_max else vector < best_vector):
            best_vector = vector
            best_versions = {name: version for name, version in selected.items()
                             if version != -1}
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


