def _round(n, mode):
    if mode == "half_up":
        return (n + 5000) // 10000
    return n // 10000


def _component_06(data):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if ident not in chosen or rank > chosen[ident][0]:
            chosen[ident] = (rank, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), data["rounding"])
        tax = _round(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None
    available = [job for job in jobs if job["id"] not in blocked]
    for group in combinations(available, k):
        ids = tuple(sorted(job["id"] for job in group))
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue
        timeline = []
        for job in group:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(timeline, key=lambda x: (x[0], x[1])):
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in group)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bit.get(start, 0)
    start_state = (start, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], start, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if coupons:
                durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                new_time = depart + duration
                if new_time > data["deadline"]:
                    continue
                left = coupons - (1 if index == 1 else 0)
                nxt = edge["v"]
                new_mask = mask | bit.get(nxt, 0)
                new_state = (nxt, new_mask, left)
                if new_time < distances.get(new_state, float("inf")):
                    distances[new_state] = new_time
                    heapq.heappush(queue, (new_time, nxt, new_mask, left))
    return {"arrival": None}


